"#!/usr/bin/env python3
import json
import subprocess
from pathlib import Path

SCRIPT_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin/scripts")
SAFE_INGEST = SCRIPT_DIR / "safe_ingest.py"
REPO = "matthewmcneill/esp32-app-foundation"

def run_ingest(subcmd, *args):
    cmd = ["python3", str(SAFE_INGEST), subcmd, "--repo", REPO, *args]
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        return None
    try:
        return json.loads(r.stdout)
    except:
        return None

prs = [266, 267, 268, 270, 271, 272, 273, 274]
issues = [80, 201, 226, 251, 252, 254, 255, 256, 269, 275, 276]

print("=== PRS STATUS ===")
for p in prs:
    res = run_ingest("pr-view", str(p))
    if res:
        labels = [l.get("name") if isinstance(l, dict) else str(l) for l in res.get("labels", [])]
        print(f"PR #{p}: state={res.get('state')} | merged={res.get('mergedAt') is not None} | title={res.get('title')} | labels={labels}")
    else:
        print(f"PR #{p}: failed to fetch")

print("\n=== ISSUES STATUS ===")
for iss in issues:
    res = run_ingest("issue-view", str(iss))
    if res:
        labels = [l.get("name") if isinstance(l, dict) else str(l) for l in res.get("labels", [])]
        print(f"Issue #{iss}: state={res.get('state')} | title={res.get('title')} | labels={labels}")
    else:
        print(f"Issue #{iss}: failed to fetch")

